  string url = 1 [(google.api.field_behavior) = REQUIRED];
}

message BatchGetLinkMetadataRequest {
  // Required. The link URLs.
  repeated string urls = 1 [(google.api.field_behavior) = REQUIRED];
}

message BatchGetLinkMetadataResponse {
